test("forward only rates scenario 1", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-10");
  expect(await ui.setRole(pg_uma, "wes", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "clerk-limit", "3.00");
  await ui.setSetting(pg_uma, "floor", "2.00");
  await ui.setSetting(pg_uma, "terms", "7");
  await ui.setSetting(pg_uma, "late-pct", "5.00");
  await ui.setSetting(pg_uma, "period-numbering-from", "2026-03-01");
  await ui.setSetting(pg_uma, "terms-B", "20");
  await ui.setSetting(pg_uma, "perm-close", "clerk");
  await ui.setSetting(pg_uma, "grace-days", "3");
  await ui.setSetting(pg_uma, "note-threshold", "1.00");
  await ui.setSetting(pg_uma, "grace-A", "5");
  await ui.setSetting(pg_uma, "proof-threshold-B", "4.00");
  expect(await ui.saveTemplate(pg_uma, {"name": "T1", "amount": "0.04", "note": "tpl"})).toBe(true);
  await ui.setSetting(pg_uma, "pot", "33.33");
  await ui.setSetting(pg_uma, "alert-threshold", "3.00");
  await ui.setSetting(pg_uma, "review-threshold", "4.00");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "5.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "7.50"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A", "contact": "ben@x"}));
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "B", "tags": "a"}));
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "C", "terms": "3"}));
  const pl_ben_1 = ui.must(await ui.addPlan(pg_uma, p_ben, {"amount": "12.50", "start": "2026-03-09", "end": "2026-04-30", "day": "15"}));
  expect(await ui.statementAsOf(pg_uma, p_ben, "2026-03-28")).toBe(false);
  await ui.setSetting(pg_uma, "policy-date", "2026-03-05");
  const c_cam_0 = ui.must(await ui.quickAdd(pg_uma, {"name": "Cam", "amount": "10.25"}, p_cam));
  const pg_wes = await ui.userPage(browser, "wes", sheet);
  expect(await ui.reassign(pg_wes, c_cam_0, "Ben")).toBe(true);
  expect(await ui.inlineGrade(pg_wes, p_ben, "C")).toBe(true);
  expect(await ui.pasteClaims(pg_wes, "Ben,25.00,2026-03-09,paste")).toBe(1);
  const c_ben_1 = await ui.claimAt(pg_wes, p_ben, 1);
  await ui.setToday(pg_wes, "2026-03-24");
  await ui.refresh(pg_wes);
  await expect(pg_wes.getByTestId("person-row-" + p_ada).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("person-row-" + p_ada).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("person-row-" + p_cam).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("person-row-" + p_cam).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("person-row-" + p_ben).getByTestId("person-claimed")).toHaveText("25.00");
  await expect(pg_wes.getByTestId("person-row-" + p_ben).getByTestId("person-due-total")).toHaveText("n/a");
  await expect(pg_wes.getByTestId("claim-row-" + c_ben_1).getByTestId("claim-due")).toHaveText("n/a");
  await expect(pg_wes.getByTestId("claim-row-" + c_ben_1).getByTestId("claim-status")).toHaveText("OPEN");
  await expect(pg_wes.getByTestId("claim-row-" + c_ben_1).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_wes.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-due")).toHaveText("n/a");
  await expect(pg_wes.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-status")).toHaveText("DRAFT");
  await expect(pg_wes.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_wes.getByTestId("rollup-claimed-total")).toHaveText("25.00");
  await expect(pg_wes.getByTestId("rollup-due-total")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("rollup-overdue-count")).toHaveText("1");
  await expect(pg_wes.getByTestId("rollup-overdue-total")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("rollup-settled-total")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("rollup-open-total")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("bulk-settle-batch")).toHaveText("");
  await expect(pg_wes.getByTestId("rollup-cut-total")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("header-people-count")).toHaveText("3");
  await expect(pg_wes.getByTestId("header-claims-DRAFT-count")).toHaveText("1");
  await expect(pg_wes.getByTestId("header-claims-OPEN-count")).toHaveText("1");
  await expect(pg_wes.getByTestId("header-claims-PENDING-count")).toHaveText("0");
  await expect(pg_wes.getByTestId("header-claims-SETTLED-count")).toHaveText("0");
  await expect(pg_wes.getByTestId("header-claims-VOID-count")).toHaveText("0");
  await expect(pg_wes.getByTestId("header-claims-REVIEW-count")).toHaveText("0");
  await expect(pg_wes.getByTestId("header-due-total")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("header-overdue-total")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("my-due-total")).toHaveText("");
  await expect(pg_wes.getByTestId("my-overdue-total")).toHaveText("");
  expect(await ui.importRates(pg_wes, "A,12.50\nC,5.00,2026-03-05")).toBe(2);
  expect(await ui.claimEditOpen(pg_wes, c_cam_0)).toBe(true);
  await ui.refresh(pg_uma);
  expect(await ui.claimEditOpen(pg_uma, c_cam_0)).toBe(false);
  await ui.refresh(pg_wes);
  expect(await ui.claimEditSave(pg_wes, c_cam_0, {"amount": "10.25"})).toBe(true);
  expect(await ui.editPerson(pg_wes, p_ben, {"grade": "B", "gradeFrom": "2026-03-28"}, {"grade": "C"})).toBe(true);
  const c_cam_0_2 = ui.must(await ui.addClaim(pg_wes, p_cam, {"amount": "10.35", "ref": "inv 7"}));
  await ui.refresh(pg_wes);
  expect(await ui.reassign(pg_wes, c_cam_0_2, "Ben")).toBe(true);
  const pg_vic = await ui.userPage(browser, "vic", sheet);
  expect(await ui.claimAction(pg_vic, c_ben_1, "settle")).toBe(false);
  expect(await ui.claimAction(pg_vic, c_cam_0, "open")).toBe(false);
  await ui.refresh(pg_vic);
  await expect(pg_vic.getByTestId("person-row-" + p_ada).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_vic.getByTestId("person-row-" + p_ada).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_vic.getByTestId("person-row-" + p_cam).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_vic.getByTestId("person-row-" + p_cam).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_vic.getByTestId("person-row-" + p_ben).getByTestId("person-claimed")).toHaveText("25.00");
  await expect(pg_vic.getByTestId("person-row-" + p_ben).getByTestId("person-due-total")).toHaveText("1.25");
  await expect(pg_vic.getByTestId("claim-row-" + c_cam_0_2).getByTestId("claim-due")).toHaveText("2.00");
  await expect(pg_vic.getByTestId("claim-row-" + c_cam_0_2).getByTestId("claim-status")).toHaveText("DRAFT");
  await expect(pg_vic.getByTestId("claim-row-" + c_cam_0_2).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_vic.getByTestId("claim-row-" + c_ben_1).getByTestId("claim-due")).toHaveText("1.25");
  await expect(pg_vic.getByTestId("claim-row-" + c_ben_1).getByTestId("claim-status")).toHaveText("OPEN");
  await expect(pg_vic.getByTestId("claim-row-" + c_ben_1).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_vic.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-due")).toHaveText("2.00");
  await expect(pg_vic.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-status")).toHaveText("DRAFT");
  await expect(pg_vic.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_vic.getByTestId("rollup-claimed-total")).toHaveText("25.00");
  await expect(pg_vic.getByTestId("rollup-due-total")).toHaveText("0.00");
  await expect(pg_vic.getByTestId("rollup-overdue-count")).toHaveText("1");
  await expect(pg_vic.getByTestId("rollup-overdue-total")).toHaveText("0.00");
  await expect(pg_vic.getByTestId("rollup-settled-total")).toHaveText("0.00");
  await expect(pg_vic.getByTestId("rollup-open-total")).toHaveText("1.25");
  await expect(pg_vic.getByTestId("bulk-settle-batch")).toHaveText("");
  await expect(pg_vic.getByTestId("rollup-cut-total")).toHaveText("0.00");
  await expect(pg_vic.getByTestId("header-people-count")).toHaveText("3");
  await expect(pg_vic.getByTestId("header-claims-DRAFT-count")).toHaveText("2");
  await expect(pg_vic.getByTestId("header-claims-OPEN-count")).toHaveText("1");
  await expect(pg_vic.getByTestId("header-claims-PENDING-count")).toHaveText("0");
  await expect(pg_vic.getByTestId("header-claims-SETTLED-count")).toHaveText("0");
  await expect(pg_vic.getByTestId("header-claims-VOID-count")).toHaveText("0");
  await expect(pg_vic.getByTestId("header-claims-REVIEW-count")).toHaveText("0");
