package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A validated rate change: the grade, its percent (two decimals), the date it applies from (null
 *  for from the beginning of time), the date it applies through (null for
 *  no end) and who sets it. */
public record RateInput(String grade, BigDecimal pct, LocalDate from, LocalDate to, String user) {
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A grade's rate as the front end reads it: the percent with two decimals and the date (yyyy-MM-dd)
 *  it applies from, null when it applies from the beginning of time; and the date it applies through,
 *  null when it has no end; and the level of the sheet it is on: 0 for the sheet's own, 1 for its parent's,
 *  and so on up; and how many versions it has (the newest is the one shown). */
public record RateResponse(String grade, String pct, String from, String to, int level, int version) {
    public static RateResponse of(String grade, BigDecimal pct, LocalDate from, LocalDate to, int version) {
        return of(grade, pct, from, to, 0, version);
    }

    public static RateResponse of(String grade, BigDecimal pct, LocalDate from, LocalDate to, int level, int version) {
        return new RateResponse(grade, pct.setScale(2).toPlainString(), from == null ? null : from.toString(),
                to == null ? null : to.toString(), level, version);
    }
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.Set;
import java.util.regex.Pattern;
import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateRate {
    private static final Set<String> GRADES = Set.of("A", "B", "C");

    /** 0.00 or more, with up to two decimals. */
    private static final Pattern PCT = Pattern.compile("\\d+(\\.\\d{1,2})?");

    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody RateRequest request, Out<RateInput> body, RoleStore roles) throws InvalidSheetException {
        roles.refuseChange(sheetId.trim(), request == null ? null : request.user());
        body.set(check(request));
    }

    /** The rate change the request asks for, checked with the rate form's rules. */
    static RateInput check(RateRequest request) throws InvalidSheetException {
        if (request == null || request.grade() == null || !GRADES.contains(request.grade())) {
            throw new InvalidSheetException("The grade must be A, B or C");
        }
        String pct = request.pct() == null ? "" : request.pct().trim();
        if (!PCT.matcher(pct).matches()) {
            throw new InvalidSheetException("The rate must be a percent of 0.00 or more with up to two decimals");
        }
        LocalDate from = date(request.from());
        LocalDate to = date(request.to());
        if (to != null && from != null && to.isBefore(from)) {
            throw new InvalidSheetException("The to-date must not be before the from-date");
        }
        return new RateInput(request.grade(), new BigDecimal(pct).setScale(2), from, to, request.user());
    }

    /** The date (yyyy-MM-dd) of the text, null when blank. */
    private static LocalDate date(String value) throws InvalidSheetException {
        String text = value == null ? "" : value.trim();
        try {
            return text.isEmpty() ? null : LocalDate.parse(text);
        } catch (DateTimeParseException e) {
            throw new InvalidSheetException("Not a date: " + text);
        }
    }
}
